53711" y1="407.509521484375" y2="407.509521484375"></line><line marker-start="url(#marker0)" stroke="#000" stroke-width="2.4" x1="205.2137680053711" x2="232.2137680053711" y1="407.509521484375" y2="407.509521484375"></line><text fill="#000000" font-family="Crimson Text" font-size="19.84" text-anchor="top" transform="translate(242.2137680053711 414.509521484375)"> Total</text><line marker-end="url(#marker0)" marker-start="url(#marker0)" stroke="#000" stroke-width="2.4" x1="113.02479858398438" x2="146.91692504882812" y1="173.0285714285714" y2="160.11428571428573"></line><line marker-end="url(#marker0)" marker-start="url(#marker0)" stroke="#000" stroke-width="2.4" x1="146.91692504882812" x2="180.80905151367188" y1="160.11428571428573" y2="125.02857142857144"></line><line marker-end="url(#marker0)" marker-start="url(#marker0)" stroke="#000" stroke-width="2.4" x1="180.80905151367188" x2="214.70117797851563" y1="125.02857142857144" y2="113.14285714285714"></line><line marker-end="url(#marker0)" marker-start="url(#marker0)" stroke="#000" stroke-width="2.4" x1="214.70117797851563" x2="248.5933044433594" y1="113.14285714285714" y2="181.94285714285715"></line><line marker-end="url(#marker0)" marker-start="url(#marker0)" stroke="#000" stroke-width="2.4" x1="248.5933044433594" x2="282.4854309082031" y1="181.94285714285715" y2="192.8"></line><line marker-end="url(#marker0)" marker-start="url(#marker0)" stroke="#000" stroke-width="2.4" x1="282.4854309082031" x2="316.37755737304684" y1="192.8" y2="202.9714285714286"></line><line marker-end="url(#marker0)" marker-start="url(#marker0)" stroke="#000" stroke-width="2.4" x1="316.37755737304684" x2="350.26968383789057" y1="202.9714285714286" y2="168.57142857142856"></line><line marker-end="url(#marker0)" marker-start="url(#marker0)" stroke="#000" stroke-width="2.4" x1="350.26968383789057" x2="384.1618103027343" y1="168.57142857142856" y2="196.34285714285716"></line><line marker-end="url(#marker0)" marker-start="url(#marker0)" stroke="#000" stroke-width="2.4" x1="384.1618103027343" x2="418.053936767578" y1="196.34285714285716" y2="242.85714285714286"></line></g></svg></figure><div aria-label="Long description for line graph titled Investigative Articles Published in the Albuquerque Journal from 2010 to 2019" class="sr-only" role="region"><ul>
<li>The line graph: <br/>
<ul>
<li>Begins at 2010, 1,076</li>
<li>Rises gradually to 2011, 1,189</li>
<li>Rises sharply to 2012, 1,496</li>
<li>Rises gradually to 2013, 1,600</li>
<li>Falls sharply to 2014, 998</li>
<li>Falls gradually to 2015, 903</li>
<li>Falls gradually to 2016, 814</li>
<li>Rises sharply to 2017, 1,115</li>
<li>Falls sharply to 2018, 872</li>
<li>Falls sharply to 2019, 465</li>
</ul>
</li>
</ul></div>
<p>Investigative journalists research and report about fraud, corruption, public hazards, and more. The graph shows the number of investigative articles published in the <em>Albuquerque Journal</em> newspaper from 2010 to 2019. According to an analyst, although the number of investigative articles published in this newspaper has varied significantly over the period shown, <span aria-label="Referenced Content" role="region"><u>the number overall has fallen since 2010</u></span>.</p>$SATQ$, $SATQ$<p>Which choice most effectively uses data from the graph to justify the underlined claim?</p>$SATQ$, $SATQ$[{"id":"af965d7f-deea-4263-8b60-4a98505195d5","content":"<p>The newspaper published approximately 1,000 investigative articles in 2010 and approximately 500 in 2019.</p>"},{"id":"c070892f-c09b-42da-9648-69b9b70102df","content":"<p>The smallest annual number of investigative articles published in the newspaper during the period shown is approximately 1,600 in 2013.&nbsp;</p>"},{"id":"8d2e5f3a-fdcc-4c96-8a07-9d6574923cb9","content":"<p>The greatest annual number of investigative articles published in the newspaper during the period shown is approximately 1,000 in 2017.&nbsp;</p>"},{"id":"d2509708-52a7-4549-80d5-8c611430f123","content":"<p>The newspaper published approximately 1,000 investigative articles in 2010 and approximately 1,600 in 2013.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["af965d7f-deea-4263-8b60-4a98505195d5"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. By comparing the number of investigative articles in 2010 to the number in 2019, we can see that the number has fallen overall. </p><p>Choice B is incorrect. This choice misreads the graph. The 1,600 articles published in 2013 was the largest annual number of investigative articles published during the period. Also, notice that the claim focuses on an overall change, while this choice just focuses on one year. We can&rsquo;t determine an overall increase or decrease by looking at just one year. Choice C is incorrect. The 1,000 articles published in 2017 wasn&rsquo;t the largest number published during the period. Also, notice that the claim focuses on an overall change, while this choice just focuses on one year. We can&rsquo;t determine an overall increase or decrease by looking at just one year. Choice D is incorrect. This choice doesn&rsquo;t justify the claim. The claim is about a decrease in articles published between 2010 and 2019. This data shows an increase in articles published over a different period (2010-2013). </p>$SATQ$, false, 0, $SATQ$OSP-KA-QUA-E001$SATQ$, $SATQ$$SATQ$, $SATQ$8253a4fd-4f31-4370-b1e4-257af3c2baab$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"e441da80","external_id":"c4867d24-bd6b-421c-9558-60415940d47d","vaultid":"6b3a5740-5fdc-4359-8dd4-571ff9c27183","uId":"9efc45cd-95f7-4b1e-bcf6-47ec56759494","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<figure class=\"image\"><svg aria-label=\"A line graph titled Investigative Articles Published in the Albuquerque Journal from 2010 to 2019. The horizontal axis has no label. It ranges from 2010 to 2019 in increments of 1. The vertical axis is labeled Number of articles. It ranges from 0 to 1,750 in increments of 250. Refer to long description.\" height=\"440.509521484375\" role=\"img\" viewbox=\"0 0 450 440.509521484375\" width=\"450\" xmlns=\"http://www.w3.org/2000/svg\"><g data-name=\"Layer 1\" id=\"ed420550-79eb-48d4-af01-cd27cdd08afd\"><defs>\n<marker id=\"marker0\" markerheight=\"6\" markerunits=\"strokeWidth\" markerwidth=\"6\" refx=\"3\" refy=\"3\">\n<polygon fill=\"#000\" points=\"3 0, 0 5.196, 6 5.196\"></polygon>\n</marker>\n<marker id=\"marker1\" markerheight=\"5\" markerunits=\"strokeWidth\" markerwidth=\"5\" refx=\"2.5\" refy=\"2.5\">\n<path d=\"M0,0 L0,5 L5,5 L5,0 z\" fill=\"#BBB\" stroke=\"#000\" stroke-width=\"1.5\"></path>\n</marker>\n<marker id=\"marker2\" markerheight=\"6\" markerunits=\"strokeWidth\" markerwidth=\"6\" refx=\"3\" refy=\"3\">\n<circle cx=\"3\" cy=\"3\" fill=\"#FFF\" r=\"1.8\" stroke=\"#000\" stroke-width=\".6\"></circle>\n</marker>\n<marker id=\"marker3\" markerheight=\"6\" markerunits=\"strokeWidth\" markerwidth=\"6\" refx=\"3\" refy=\"3\">\n<polygon fill=\"#999\" points=\"0.5 3, 2.3 2.3, 3 0.5, 3.7 2.3, 5.5 3, 3.7 3.7, 3 5.5, 2.3 3.7, 0.5 3\" stroke=\"#000\" stroke-linejoin=\"round\" stroke-width=\".5\"></polygon>\n</marker>\n</defs><line fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\" x1=\"96.0787353515625\" x2=\"435\" xmlns=\"http://www.w3.org/2000/svg\" y1=\"96\" y2=\"96\"></line><line fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\" x1=\"90.0787353515625\" x2=\"102.0787353515625\" xmlns=\"http://www.w3.org/2000/svg\" y1=\"96\" y2=\"96\"></line><text fill=\"#000000\" font-family=\"Crimson Text\" font-size=\"19.84\" text-anchor=\"end\" transform=\"translate(84.0787353515625 102)\">1,750</text><line fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\" x1=\"96.0787353515625\" x2=\"435\" xmlns=\"http://www.w3.org/2000/svg\" y1=\"124.57142857142857\" y2=\"124.57142857142857\"></line><line fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\" x1=\"90.0787353515625\" x2=\"102.0787353515625\" xmlns=\"http://www.w3.org/2000/svg\" y1=\"124.57142857142857\" y2=\"124.57142857142857\"></line><text fill=\"#000000\" font-family=\"Crimson Text\" font-size=\"19.84\" text-anchor=\"end\" transform=\"translate(84.0787353515625 130.57142857142856)\">1,500</text><line fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0